import catalog from "./country-catalog.json";

export type Continent =
  | "Europe"
  | "Asia"
  | "Africa"
  | "North America"
  | "South America"
  | "Oceania"
  | "Antarctica";

export const CONTINENTS: readonly Continent[] = [
  "Europe",
  "Asia",
  "Africa",
  "North America",
  "South America",
  "Oceania",
  "Antarctica",
];

export type Country = {
  key: string;
  name: string;
  flag: string;
  continent: Continent;
  unMember: boolean;
  hasShape: boolean;
};

// Generated by scripts/gen-country-catalog.mjs: never edit the JSON by hand.
export const COUNTRIES: readonly Country[] = catalog as Country[];

export const UN_MEMBER_TOTAL: number = COUNTRIES.filter((c) => c.unMember).length;

const BY_KEY = new Map(COUNTRIES.map((c) => [c.key, c]));

// Atlas shapes that carry no id, matched by name.
const SLUG_BY_NAME: Record<string, string> = {
  Kosovo: "kosovo",
  "N. Cyprus": "n-cyprus",
  Somaliland: "somaliland",
};

export function countryByKey(key: string): Country | undefined {
  return BY_KEY.get(key);
}

export function isCountryKey(key: unknown): key is string {
  return typeof key === "string" && BY_KEY.has(key);
}

/** Catalog key for a raw world-atlas feature, or null when it is not markable. */
export function shapeKey(f: { id?: string | number; properties: { name: string } }): string | null {
  if (f.id !== undefined) return typeof f.id === "string" && BY_KEY.has(f.id) ? f.id : null;
  const slug = SLUG_BY_NAME[f.properties.name];
  return slug && BY_KEY.has(slug) ? slug : null;
}
